CardSpoke_MODS.register('quick-note', {
  onLoad: function(ctx) {
    if (document.getElementById('mod-quick-note-btn')) return;
    var btn = document.createElement('button');
    btn.id = 'mod-quick-note-btn';
    btn.textContent = '+';
    btn.title = 'Quick Note: Create a new card';
    btn.setAttribute('aria-label', 'Create a new card');
    btn.addEventListener('click', function() {
      var title = 'Quick Note ' + new Date().toLocaleString();
      var id = storeAPI.createCard({ title: title, body: '' });
      if (id) {
        storeAPI.showToast('Created: ' + title, 'success');
      }
    });
    document.body.appendChild(btn);
    ctx.logger.info('Quick Note button added');
  },
  onDisable: function(ctx) {
    var btn = document.getElementById('mod-quick-note-btn');
    if (btn) btn.remove();
    ctx.logger.info('Quick Note button removed');
  },
  onUninstall: function(ctx) {
    var btn = document.getElementById('mod-quick-note-btn');
    if (btn) btn.remove();
  }
});
